@Target(ElementType.METHOD) @interface Audited {}
@Retention(RetentionPolicy.RUNTIME) @Target(ElementType.METHOD) @interface AuditedRt {}

class RealPayment {
    @Audited @AuditedRt public String pay(long a) { return "paid"; }
}

Method m = RealPayment.class.getMethod("pay", long.class);
System.out.println(m.isAnnotationPresent(Audited.class) + " " + m.isAnnotationPresent(AuditedRt.class));
